import React, { useState, useEffect } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { casesAPI } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';
import CaseOpeningAnimation from '../components/CaseOpeningAnimation';

const CaseDetailPage = () => {
  const { balance, updateBalance } = useAuth();
  const { caseId } = useParams();
  const navigate = useNavigate();

  const [caseData, setCaseData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showAnimation, setShowAnimation] = useState(false);
  const [animationCaseId, setAnimationCaseId] = useState(null);
  const [wonItemFromAnimation, setWonItemFromAnimation] = useState(null);

  useEffect(() => {
    const fetchCaseDetails = async () => {
      try {
        const response = await casesAPI.getCaseById(caseId);
        setCaseData(response.data);
      } catch (err) {
        console.error(err);
        setError('Failed to load case details');
      } finally {
        setLoading(false);
      }
    };

    if (caseId) {
      fetchCaseDetails();
    }
  }, [caseId]);

  const handleOpenCase = (count) => {
    // Currently the animation opens one case at a time.
    console.log('Opening case count:', count);

    setAnimationCaseId(caseId);
    setShowAnimation(true);
  };

  const handleAnimationComplete = async (wonItem) => {
    setWonItemFromAnimation(wonItem);
    await updateBalance();
  };

  const handleAnimationClose = () => {
    setShowAnimation(false);
    setWonItemFromAnimation(null);
    setAnimationCaseId(null);
  };

  const handleCelebrationClose = () => {
    setWonItemFromAnimation(null);
  };

  if (loading) {
    return (
      <div className="container">
        <div className="text-center py-5">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">
              Loading...
            </span>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-6">

            <div className="alert alert-danger">
              {error}
            </div>

            <Link
              className="btn btn-outline-primary"
              to="/cases"
            >
              ← Back to Cases
            </Link>

          </div>
        </div>
      </div>
    );
  }

  if (!caseData) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">

            <div className="text-center py-5">
              <h3>Case not found</h3>

              <Link
                className="btn btn-outline-primary"
                to="/cases"
              >
                ← Back to Cases
              </Link>
            </div>

          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">

      {/* Header */}
      <div className="row mb-4">

        <div className="col-md-8">
          <h1 className="gradient-text">
            {caseData.name}
          </h1>

          <p className="lead">
            {caseData.description ||
              'A mysterious case with valuable rewards'}
          </p>
        </div>

        <div className="col-md-4 text-end">
          <div className="d-flex flex-column align-items-end">

            <span className="badge bg-primary fs-5 mb-2">
              {caseData.price.toLocaleString()} €
            </span>

            <h2>
              Balance:{' '}
              <span className="text-success">
                {balance.toLocaleString()} €
              </span>
            </h2>

          </div>
        </div>

      </div>

      {/* Case Image */}
      <div className="text-center mb-5">

        <ImageWithFallback
          src={caseData.image_url}
          alt={caseData.name}
          className="case-detail-image img-fluid"
          style={{
            maxWidth: '300px',
            maxHeight: '300px',
            borderRadius: '16px'
          }}
        />

      </div>

      {/* Case Contents */}
      <div className="row mb-5">

        <div className="col-12">

          <div className="card">

            <div className="card-header">
              <h5 className="mb-0">
                Case Contents
              </h5>
            </div>

            <div className="card-body">

              <div className="row g-4">
                {(caseData.items || []).map((item) => (
                  <div key={item.id} className="col-md-3 col-sm-6">
                    <div className="card-item text-center p-3 border rounded h-100">
                      <div className="item-icon mb-3">
                        <ImageWithFallback
                          src={item.image_url}
                          alt={item.name}
                          className="img-fluid"
                          style={{ width: '90px', height: '90px', objectFit: 'contain' }}
                        />
                      </div>
                      <div className="item-name fw-medium">{item.name}</div>
                      <div className="text-muted small mt-1">{item.category}</div>
                      <div className="item-rarity badge mt-2" style={{ backgroundColor: item.color || '#6c757d' }}>
                        {item.rarity}
                      </div>
                      <div className="item-probability text-muted small mt-2">
                        {Number(item.probability).toFixed(2)}%
                      </div>
                      <div className="small text-muted">
                        {Number(item.virtual_value).toLocaleString()} €
                      </div>
                    </div>
                  </div>
                ))}
              </div>

            </div>

          </div>

        </div>

      </div>

      {/* Open Options */}
      <div className="row g-4 mb-5">

        <div className="col-12">

          <h4>
            Open Options
          </h4>

          <button
            type="button"
            className="btn btn-primary w-100"
            onClick={() => handleOpenCase(1)}
          >
            Open for {Number(caseData.price).toLocaleString()} €
          </button>
          <div className="form-text mt-2">One opening per animation. The backend chooses the winner before the roulette starts.</div>

        </div>

      </div>

      {/* Warning */}
      <div className="alert alert-info">

        <i className="bi bi-info-circle me-2"></i>

        Virtual currency — no real-money value

      </div>

      {/* Case Opening Animation */}
      {showAnimation && (
        <div
          className="opening-overlay active"
          onClick={handleAnimationClose}
        >

          <div
            className="opening-overlay-content"
            onClick={(e) => e.stopPropagation()}
          >

            <CaseOpeningAnimation
              caseId={animationCaseId}
              onComplete={handleAnimationComplete}
              onClose={handleAnimationClose}
            />

          </div>

        </div>
      )}

      {/* Won Item Celebration */}
      {wonItemFromAnimation && !showAnimation && (
        <div
          className="celebration-overlay active"
          onClick={handleCelebrationClose}
        >

          <div
            className="celebration-content"
            onClick={(e) => e.stopPropagation()}
          >

            <h3>
              Congratulations!
            </h3>

            <p>
              You won: {wonItemFromAnimation.name}
            </p>

            <div className="won-item-image">

              <ImageWithFallback
                src={wonItemFromAnimation.image_url}
                alt={wonItemFromAnimation.name}
                className="celebration-item-image"
                style={{
                  width: '120px',
                  height: '120px'
                }}
              />

            </div>

          </div>

        </div>
      )}

    </div>
  );
};

export default CaseDetailPage;
